/* saleson.shop.donation.NgDonationMapper.updateCntrBlcePoint */
UPDATE G_CNTR
SET CNTR_BLCE_POINT = (CNTR_POINT - (SELECT IFNULL(SUM(cntr_use_point), 0) FROM g_cntr_use_point b WHERE CNTR_SN = #{cntrSn} AND b.use_se_code = '1'))
WHERE CNTR_SN = #{cntrSn}

mapper.select:
/* saleson.shop.donation.NgDonationMapper.selectRelayLogListCount */
SELECT
    COUNT(*)
FROM g_relay_log a
INNER JOIN op_user b ON a.user_id = b.user_id
INNER JOIN g_locgov c ON a.cntr_locgov_code = c.locgov_code
WHERE a.frst_regist_pnttm BETWEEN TO_DATETIME(#{srchStartLogDate} || ' 00:00:00.000', 'YYYYMMDD HH24:MI:SS.FF') AND TO_DATETIME(#{srchEndLogDate} || ' 23:59:59.999', 'YYYYMMDD HH24:MI:SS.FF')

    AND a.relay_type = #{srchRelayType}


    AND a.relay_result_code = #{srchRelayResultCode}




            AND a.user_id = #{srchTxt}


            AND b.user_name LIKE CONCAT('%', (SELECT crypto_enc('normal', #{srchTxt},'')), '%')

/* saleson.shop.donation.NgDonationMapper.selectRelayLogList */ SELECT a.user_id , CRYPTO_DEC('normal', b.login_id , '', 0) AS login_id , CRYPTO_DEC('normal', b.user_name, '', 0) AS user_name , a.relay_type , f.label AS relay_type_name , a.cntr_locgov_code , c.locgov_nm AS cntr_locgov_code_name , d.elctrn_pay_no , CASE WHEN a.relay_result_code = '100' THEN '성공( code : ' || relay_result_code || ' )' ELSE '실패( code : ' || relay_result_code || ' )' END AS relay_result_code , a.frst_regist_pnttm FROM g_relay_log a INNER JOIN op_user b ON a.user_id = b.user_id INNER JOIN g_locgov c ON a.cntr_locgov_code = c.locgov_code LEFT OUTER JOIN g_cntr d ON a.cntr_sn = d.cntr_sn LEFT OUTER JOIN op_common_code f ON f.code_type= 'RELAY_TYPE' AND a.relay_type = f.id WHERE a.frst_regist_pnttm BETWEEN TO_DATETIME(#{srchStartLogDate} || ' 00:00:00.000', 'YYYYMMDD HH24:MI:SS.FF') AND TO_DATETIME(#{srchEndLogDate} || ' 23:59:59.999', 'YYYYMMDD HH24:MI:SS.FF')
AND a.relay_type = #{srchRelayType}
AND a.relay_result_code = #{srchRelayResultCode}
AND b.login_id = (SELECT crypto_enc('normal', #{srchTxt},''))
AND b.user_name = (SELECT crypto_enc('normal', #{srchTxt},''))
AND (b.login_id = (SELECT crypto_enc('normal', #{srchTxt},'')) OR b.user_name = (SELECT crypto_enc('normal', #{srchTxt},'')))
ORDER BY a.frst_regist_pnttm DESC

