mapper.select:
    /* saleson.shop.donation.NgDonationMapper.selectGifStndBugaCount */
    SELECT
        COUNT(*)
    FROM g_next_buga_request buga
    WHERE 1 = 1

	 	AND buga.lvy_ymd >= #{srchStartLogDate}
	 	AND buga.lvy_ymd  <= #{srchEndLogDate}


	 	AND buga.buga_status_cd = #{bugaStatusCd}


	 	AND buga.link_rst_cd = #{linkRstCd}


	 	AND buga.link_rst_msg LIKE '%'|| #{epayNo} || '%'




			 	AND buga.link_rst_cd = '000'


			 	AND ( buga.link_rst_cd  <>  '000' OR buga.link_rst_cd is null )




	 	AND buga.pyr_nm = crypto_enc('normal',#{srchpyrNm},'')

/* saleson.shop.donation.NgDonationMapper.selectGifStndBugaList */ SELECT gov.upper_locgov_nm , gov.locgov_nm , buga.link_mng_key , buga.sgb_cd , buga.link_trgt_cd , buga.dpt_cd , buga.spcl_fis_biz_cd , buga.fyr , buga.act_se_cd , buga.rprs_txm_cd , buga.oper_item_cd , buga.lvy_ymd , buga.frst_pct_amt , buga.frst_pid_ymd , buga.pyr_se_cd , buga.pyr_no , crypto_dec('normal', buga.pyr_nm, '', 0) as pyr_nm , buga.rprs_pyr_no , buga.rprs_pyr_nm , buga.pyr_stt_cd , buga.lotno_road_addr_se_cd , buga.zip , buga.road_nm_cd , buga.bmno , buga.bsno , buga.stdg_cd , buga.dong_cd , crypto_dec('normal', buga.road_nm_daddr, '', 0) as road_nm_daddr , buga.gl_nm , buga.mng_item_cn1 , buga.buga_status_cd , buga.link_rst_cd , buga.link_rst_msg , buga.frst_regist_pnttm FROM g_next_buga_request buga LEFT JOIN g_locgov gov ON buga.sgb_cd = gov.administ_instt_code WHERE 1 = 1
AND buga.lvy_ymd >= #{srchStartLogDate} AND buga.lvy_ymd <= #{srchEndLogDate}
AND buga.buga_status_cd = #{bugaStatusCd}
AND buga.link_rst_cd = #{linkRstCd}
AND buga.link_rst_msg LIKE '%'|| #{epayNo} || '%'
AND buga.link_rst_cd = '000'
AND ( buga.link_rst_cd <> '000' OR buga.link_rst_cd is null )
AND buga.pyr_nm = crypto_enc('normal',#{srchpyrNm},'')
ORDER BY buga.frst_regist_pnttm DESC

